'use strict';
/* THROWAWAY. Question: which complete six-scale composition best matches the
 * approved references? Three structural variants share existing atlas data and
 * cartography. Read-only, memory-only interactions; never a production module. */
(()=>{
 const levels=['World','Continent','Region','Metro','Campus','Facility'];
 const variants={A:'Editorial atlas',B:'Research workbench',C:'Immersive explorer'};
 const params=new URLSearchParams(window.ATLAS_DESIGN_ENTRY_SEARCH||location.search);
 const dp={variant:params.get('variant')||'A',level:Math.max(0,levels.map(x=>x.toLowerCase()).indexOf(params.get('scale')||'world')),site:params.get('site')||'amazon-anthropic-new-carlisle',phase:params.get('phase')||'snapshot',tab:params.get('tab')||'overview',scene:params.get('scene')||'research',claim:params.get('claim')||'helios-phase1-it',country:params.get('country')||'all',company:'all',evidence:'all',region:'all',page:'landscape',labels:true,layers:false,context:true,roads:true,expanded:false,compare:[],notes:{},modal:null,drawer:null,search:'',showState:false};
 if(!variants[dp.variant])dp.variant='A';
 let map=null,toastTimer=null,lastFocus=null;
 const mappedRecord=()=>catalogFeature('osm-way-1121454055');
 const selected=()=>site(dp.site)||site('coreweave-helios');
 const mapped=()=>dp.level>=4&&dp.scene==='mapped';
 const number=v=>v==null?'Not disclosed':fmt(v);
 const unit=(v,unit='MW')=>v==null?'Not disclosed':`${v>=1000&&unit==='MW'?fmt(v/1000,2)+' GW':fmt(v)+' '+unit}`;
 const power=s=>spatialPower(s,dp.phase);
 const itRows=s=>primaryPowerRows(s).filter(r=>r.boundary==='critical_it'&&!primaryIsContext(r));
 const sources=s=>primarySourceIds(s).map(primarySource).filter(Boolean);
 const chosenClaim=()=>itRows(selected()).find(x=>x.id===dp.claim)||itRows(selected())[0];
 const link=(action,label,value='',cls='')=>`<button class="${cls}" data-dp="${action}" data-value="${esc(value)}">${label}</button>`;
 const cite=id=>link('source',esc(id),id,'dp-source-button');
 const pill=(label,cls='')=>`<span class="dp-pill ${cls}">${esc(label)}</span>`;
 const kicker=(n,title,action='')=>`<div class="dp-kicker"><span>${n} / ${title}</span>${action?link(action,'↗'):''}</div>`;
 function syncResearch(){state.view='overview';state.spatialLevel=Math.min(dp.level,3);state.spatialSelected=dp.site;state.spatialPhase=dp.phase;state.spatialEvidence=dp.evidence;state.spatialLabels=dp.labels;state.spatialRoads=dp.roads;state.filter={q:'',company:dp.company,country:dp.country,review:'all',stage:'all'};}
 function scope(){syncResearch();const sc=spatialScope(Math.min(dp.level,3),selected());if(dp.region!=='all'&&dp.level<=1)sc.sites=sc.sites.filter(s=>spatialContinent(s)===dp.region);return sc;}
 function updateURL(replace=false){const q=new URLSearchParams({variant:dp.variant,scale:levels[dp.level].toLowerCase()});if(dp.site!=='amazon-anthropic-new-carlisle')q.set('site',dp.site);if(dp.phase!=='snapshot')q.set('phase',dp.phase);if(dp.scene!=='research')q.set('scene',dp.scene);if(dp.tab!=='overview')q.set('tab',dp.tab);if(dp.claim!=='helios-phase1-it')q.set('claim',dp.claim);if(dp.country!=='all')q.set('country',dp.country);history[replace?'replaceState':'pushState'](null,'',location.pathname+'?'+q);}
 function go(change,replace=false){Object.assign(dp,change);dp.layers=false;updateURL(replace);draw();window.scrollTo({top:0,behavior:'instant'});}
 function toast(message){document.querySelector('.dp-toast')?.remove();const el=document.createElement('div');el.className='dp-toast';el.setAttribute('role','status');el.textContent=message;document.body.append(el);clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.remove(),3500);}
 function sidebar(){const entries=[['landscape','overview','The landscape'],['directory','facilities','Facility directory'],['companies','companies','Company universe'],['connections','contracts','Contracts & connections'],['investment','investment','Investment lens'],['research','reports','Research library']];return `<aside class="dp-side"><button class="dp-brand" data-dp="home"><span class="dp-brand-mark">◉</span><span>COMPUTE<small>ATLAS</small></span></button><div class="dp-side-label">INFRASTRUCTURE & CAPITAL</div><nav aria-label="Main navigation">${entries.map(([id,ico,label])=>link('page',icon(ico)+`<span class="dp-nav-label">${label}</span>`,id,dp.page===id?'active':'')).join('')}</nav><hr><nav>${link('tour',icon('stories')+'<span class="dp-nav-label">Guided explorations</span>')}${link('compare',icon('costs')+'<span class="dp-nav-label">Compare projects</span>')}</nav><div class="dp-side-bottom">${link('search','⌕ &nbsp; Search everything <kbd>/</kbd>')}${link('shelf','☆ &nbsp; Research shelf')}${link('monitor','▤ &nbsp; Sources & updates')}<div class="dp-status"><i></i>RESEARCH PUBLICATION</div><p>Source dates travel with each claim.<br>Coverage is partial; unknown stays visible.</p>${link('method','Methodology & map attribution ↗')}</div></aside>`;}
 function breadcrumbs(){const s=selected();let path=[['The landscape',0]];if(dp.level>=1)path.push([mapped()?'Europe':spatialContinent(s)==='Asia'?'Asia':'North America ↔ Europe',1]);if(dp.level>=2)path.push([mapped()?'France':spatialScope(2,s).label,2]);if(dp.level>=3)path.push([mapped()?'Paris–Saint-Denis':spatialScope(3,s).label,3]);if(dp.level>=4)path.push([mapped()?'Equinix PA9X':s.name,4]);if(dp.level===5)path.push([mapped()?'Source building':chosenClaim()?.scope||'Project evidence',5]);return path.map(([title,l],i)=>(i?'<span>›</span>':'')+link('level',esc(title),l,i===path.length-1?'current':'')).join('');}
 function topbar(){return `<header class="dp-top">${link('menu','☰','','dp-mobile-menu')}<div class="dp-crumbs">${breadcrumbs()}</div>${link('search','⌕ <span>Search a company, site, source…</span><kbd>⌘ K</kbd>','','dp-search-launch')}<div class="dp-data-date">PUBLICATION<b>10 OCT 2026</b></div>${link('method','?','','dp-help')}</header>`;}
 function intro(){const s=selected(),r=mappedRecord();let title,desc;if(dp.level===0){title='A global view<br>of compute capital.';desc='Explore the physical infrastructure behind AI. Follow the places, power and counterparties — from the world to a single facility.';}else if(dp.level===1){title=spatialScope(1,s).label==='North America ↔ Europe'?'North America ↔ Europe.<br>The core of a connected system.':esc(spatialScope(1,s).label)+'.<br>The physical network behind AI.';desc='Follow the major markets and the companies behind them. Compare dated site estimates while keeping local coverage in view.';}else if(dp.level===2){title=spatialScope(2,s).label==='US East & Midwest'?'The Midwest and East Coast,<br>powering what’s next.':esc(spatialScope(2,s).label)+'.<br>Follow the physical footprint.';desc='Explore the regional footprint. Select a project to inspect its power, phase commitments, ownership and evidence.';}else if(dp.level===3){title=s.id==='amazon-anthropic-new-carlisle'?'Chicago to New Carlisle.':esc(spatialScope(3,s).label)+'.';desc='Power, land and compute converge in the Midwest. Select a named project and follow its development evidence.';}else{title=esc(mapped()?r.name:s.name)+(dp.level===4?' campus.':'');desc=mapped()?'Explore the mapped footprint and its source. Geometry, display height and operating capacity each retain their own evidence boundary.':'Inspect the project’s phases, counterparties and original disclosures. Every quantity keeps its reporting date and boundary.';}return `<section class="dp-intro"><div><div class="dp-eyebrow">${dp.level<4?'COMPUTE, FROM THE GROUND UP':'FACILITY & CAMPUS'}</div><h1>${title}</h1>${dp.level>=4?`<p class="dp-location">⌖ ${esc(mapped()?'Saint-Denis, France':s.location+', '+s.country)}</p>`:''}</div><div class="dp-intro-aside"><p>${desc}</p>${link(dp.level<4?'tour':'shelf',dp.level<4?'Take the five-stop tour ↗':'Add to research shelf +','','dp-primary')}</div></section>`;}
 function scaleStrip(){return `<nav class="dp-map-scale" aria-label="Geographic scale">${levels.map((name,i)=>(i?'<span class="dp-scale-sep">›</span>':'')+link('level',`<span>${i+1}</span>${name}`,i,dp.level===i?'active':'')).join('')}</nav>`;}
 function tabs(){return `<nav class="dp-tabs" aria-label="Project sections">${[['overview','Overview'],['power','Power & phases'],['technical','Technical design'],['timeline','Timeline'],['counterparties','Counterparties'],['evidence','Sources & evidence']].map(([id,title])=>link('tab',title,id,dp.tab===id?'active':'')).join('')}</nav>`;}
 function legend(){return `<div class="dp-map-legend"><div><i></i>Reviewed independent estimate</div><div><i class="model"></i>Imported independent estimate</div><div><i class="native"></i>Native unit / contract record</div>${dp.level>=2?'<div><i class="dp-line-key"></i>Generalized roads & boundaries</div>':''}${dp.context?'<div><i class="context"></i>Community locations · no capacity implied</div>':''}</div>`;}
 function layerPanel(){return dp.layers?`<section class="dp-layer-panel"><h3>Map layers</h3>${[['context','Community locations','5,265 map features, independent of capacity'],['roads','Roads & boundaries','Generalized reference cartography'],['labels','Place & project labels','Labels follow the visible scale']].map(([key,title,detail])=>`<label><input type="checkbox" data-dp-layer="${key}" ${dp[key]?'checked':''}><span>${title}<small>${detail}</small></span></label>`).join('')}<div class="dp-layer-empty">Utility and fibre layers appear here once source and service relationships are reviewed.</div>${link('method','Sources & map attribution ↗','','dp-text')}</section>`:'';}
 function mapTools(){return `<div class="dp-map-tools">${link('labels','Aa','','')}${link('zoom','+','in')}${link('zoom','−','out')}${link('expand',dp.expanded?'↙':'⛶')}${link('reset','◎')}</div>`;}
 function mapPanel(sc){const isScene=dp.level>=4,title=isScene?(mapped()?'Campus source geometry':'Project phase evidence'):sc.label;return `<section class="dp-map-panel ${isScene?'dp-scene':''}" aria-label="${esc(title)}">${mapped()||!isScene?'<canvas id="dp-map" tabindex="0" aria-label="Interactive map; drag to rotate or pan, scroll to zoom"></canvas>':fallbackScene()}<header class="dp-map-top"><div><div class="dp-map-title">${esc(title)}</div><div class="dp-map-subtitle">${isScene?(mapped()?'OSM source outline · illustrative height':'Independent source scopes · no established footprint'):`${sc.sites.length} named records · ${dp.phase==='snapshot'?'dated snapshot estimates':'target estimates'}`}</div></div><div class="dp-toggle">${isScene?[['research','Evidence'],['mapped','Mapped example']].map(([id,label])=>link('scene',label,id,dp.scene===id?'active':'')).join(''):[['snapshot','Snapshot'],['target','Target'],['layers','Layers ≡']].map(([id,label])=>link(id==='layers'?'layers':'phase',label,id,dp.phase===id||id==='layers'&&dp.layers?'active':'')).join('')}</div></header>${scaleStrip()}${mapped()?'<div class="dp-geometry-boundary">COMMUNITY GEOMETRY · HEIGHT ILLUSTRATIVE, NOT MEASURED</div>':''}${!isScene?legend():mapped()?'<div class="dp-geometry-note">OSM outline · one mapped feature<br>Geometry does not establish operating IT capacity.</div>':''}${layerPanel()}<div class="dp-map-bottom"><div>${!isScene?`<div class="dp-map-chips">${(dp.level<=1?[['all','All'],['North America','N. America'],['Europe','Europe'],['Asia','Asia'],['Middle East','Middle East']]:[['filter','Filters'],['list','Facilities'],['compare','Compare']]).map(([id,title])=>link(dp.level<=1?'region':id,title,id,dp.region===id?'active':'')).join('')}</div>`:''}<div class="dp-coordinates">${isScene?(mapped()?'SOURCE GEOMETRY · DRAG TO ORBIT · SCROLL TO ZOOM':'PHASE SCOPES ARE NOT BUILDING IDENTITIES'):dp.level<=1?'DRAG TO ROTATE · SELECT A CLUSTER TO EXPLORE':'MERCATOR · APPROXIMATE RESEARCH ANCHORS'}</div></div>${mapTools()}</div>${!isScene&&!sc.sites.length?`<div class="dp-map-empty"><h3>No projects match this view.</h3><p>Broaden your filters. This does not establish that the region has no data centers.</p>${link('clear-filters','Clear filters','','dp-primary')}</div>`:''}</section>`;}
 function fallbackScene(){const s=selected(),rows=itRows(s).slice(0,3);const data=rows.length?rows:['snapshot','target'].filter(p=>spatialPower(s,p)!=null).map(p=>({id:p,scope:p==='snapshot'?'Dated snapshot':'Projected end-state',value:spatialPower(s,p),unit:'MW',status:'Independent estimate',as_of:s[p]?.date}));return `<div class="dp-scene-placeholder-label">EVIDENCE SCHEMATIC · GEOMETRY NOT ESTABLISHED</div><div class="dp-fallback-diagram">${data.length?data.map(r=>link('claim',`<span>${esc(r.scope)}</span><b>${number(r.value)}<small> ${esc(r.unit)}</small></b><small>${esc(statusLabel(r.status))}<br>${esc(r.as_of||'Date not disclosed')}</small>`,r.id,'dp-scope-node '+(r.id===chosenClaim()?.id?'active':''))).join(''):'<p>No comparable IT-power scope is disclosed. Native quantities remain in the dossier.</p>'}</div><div class="dp-fallback-axis"><span>Disclosed scopes and modeled estimates retain separate boundaries</span>${link('geometry-plan','Geometry review ↗','','dp-text')}</div>`;}
 function kpis(sc){const xs=sc.sites,agg=spatialAggregate(xs,dp.phase),targets=spatialAggregate(xs,'target');const reviewed=xs.filter(s=>primarySourceIds(s).length).length;const values=[[unit(agg.mw),dp.phase==='snapshot'?'Named-site IT estimate':'Named-site target IT estimate',`${agg.known} comparable estimates · partial coverage`],[String(xs.length),'Named projects in this view',`${agg.unknown} native / unknown IT-MW`],[unit(targets.mw),'Projected end-state estimate',`${targets.known} modeled targets · not incremental`],[String(reviewed),'Projects with source review','Project-specific claims · inspect coverage']];return `<div class="dp-kpis">${values.map(([v,l,n])=>`<div class="dp-kpi"><div class="dp-kpi-label">${l}</div><div class="dp-kpi-value">${v}</div><div class="dp-kpi-note">${n}</div></div>`).join('')}</div>`;}
 function ranking(xs,phase='snapshot'){return spatialTopSites(xs,phase,3).map((s,i)=>link('select',`<span class="dp-rank-index">${i+1}</span><span>${esc(s.name)}<small>${esc(s.location)}</small></span><b>${unit(spatialPower(s,phase))} ↗</b>`,s.id,'dp-rank')).join('');}
 function companyWords(xs){return `<div class="dp-company-words">${spatialCompanies(xs).slice(0,6).map(({c})=>link('company',`<i style="background:${esc(c.color)}"></i>${esc(c.name)}`,c.id)).join('')}</div>`;}
 function rail(sc){if(dp.level>=4)return facilityRail();if(dp.level>=2)return localRail(sc);const agg=spatialAggregate(sc.sites,dp.phase),countries=new Set(sc.sites.map(s=>s.country)).size;return `<aside class="dp-rail" aria-label="Analysis and evidence"><section class="dp-rail-section">${kicker('01','GLOBAL TAKEAWAY','method')}<h2>${dp.level===0?'Compute is a<br>physical asset class.':'A connected system.<br>Uneven evidence.'}</h2><p>${sc.sites.length} named projects across ${countries} countries. Follow power, ownership and capital from a place to a source.</p><p class="dp-note">${agg.known} comparable IT estimates. This collection covers named projects; it is not a global capacity census.</p></section><section class="dp-rail-section">${kicker('02','WHERE CAPACITY IS PLANNED','directory')}<h2>The next buildout,<br>project by project.</h2>${ranking(sc.sites,'target')}<p class="dp-note">Targets retain their source date. End-state targets are not incremental additions or delivered capacity.</p></section><section class="dp-rail-section">${kicker('03','CAPITAL & COUNTERPARTIES','investment')}<h2>The companies<br>behind the footprint.</h2>${companyWords(sc.sites)}${link('investment','Open the investment lens ↗','','dp-text')}</section></aside>`;}
 function localRail(sc){const s=selected(),count=primarySourceIds(s).length;return `<aside class="dp-rail"><section class="dp-rail-section dp-selection">${kicker('01',dp.level===2?'SELECTED PROJECT':'SELECTED CAMPUS','dossier')}<h2 class="dp-selected-name">${esc(s.name)}</h2><p>${esc(s.location)}</p><div style="margin-top:9px">${pill(s.review==='reviewed-model'?'Independent estimate':'Source record','model')} ${pill(count+' primary documents')}</div><div class="dp-selection-metrics"><div><b>${unit(spatialPower(s,'snapshot'))}</b><span>Dated snapshot IT estimate</span></div><div><b>${unit(spatialPower(s,'target'))}</b><span>Modeled end-state</span></div></div><p class="dp-note">${esc(s.snapshot?.date||'Date not disclosed')} snapshot. Compare scopes in the full dossier.</p><div class="dp-selection-actions">${link('level','Explore this campus →',4,'dp-primary')}${link('add-compare','+ Compare','','dp-quiet')}</div></section><section class="dp-rail-section">${kicker('02','LOCAL POWER & DEVELOPMENT','timeline')}<h2>A place, with<br>its own constraints.</h2><p>${esc(s.caveats?.[0]||'Public disclosures do not establish surveyed location or live facility utilization.')}</p><div class="dp-research-buttons">${link('tab','↗ Power & disclosed commitments','power')}${link('tab','↗ Development chronology','timeline')}${link('geometry-plan','↗ Geometry & infrastructure review')}</div></section><section class="dp-rail-section">${kicker('03','REGIONAL FOOTPRINT','directory')}<h2>Other projects<br>in this view.</h2>${ranking(sc.sites.filter(x=>x.id!==s.id),dp.phase)}<p class="dp-note">${sc.sites.length} named records. Nearby facilities retain separate identities and capacity scopes.</p></section></aside>`;}
 function facilityRail(){const s=selected(),r=mappedRecord(),claim=chosenClaim();if(mapped())return `<aside class="dp-rail"><section class="dp-rail-section dp-selection">${kicker('01','SELECTED SOURCE FEATURE','geometry-plan')}<h2 class="dp-selected-name">${esc(r.name)}</h2><p>Equinix · source-tagged building</p><div class="dp-spotlight-number">Source outline.</div><p class="dp-boundary">Capacity not established by this geometry.</p><div class="dp-selection-metrics"><div><b>12 m</b><span>Illustrative display height</span></div><div><b>v${r.source_version}</b><span>OSM feature version</span></div></div><p class="dp-note">Last mapped edit ${r.updated_at.slice(0,10)}. A building outline does not establish surveyed height, live IT load or a research-project link.</p><div class="dp-selection-actions">${link('geometry-source','Open geometry source ↗','','dp-primary')}</div></section><section class="dp-rail-section">${kicker('02','INSPECT THE GEOMETRY','geometry-plan')}<h2>Every shape<br>has a provenance.</h2><div class="dp-attribute"><span>Mapped feature</span><b>${esc(r.id)}</b></div><div class="dp-attribute"><span>Coordinate basis</span><b>Center of source geometry bounds</b></div><div class="dp-attribute"><span>Measured height</span><b>Not tagged</b></div><div class="dp-attribute"><span>Operating IT capacity</span><b>Not established</b></div><p class="dp-note">Campus and nearby context never become additional capacity.</p></section><section class="dp-rail-section">${kicker('03','CAMPUS RESEARCH PATH','geometry-plan')}<h2>What needs<br>verification.</h2><p>Match the exact facility identity, corroborate its location, obtain redistributable imagery and review building-to-phase links.</p>${link('geometry-plan','Open review checklist ↗','','dp-text')}</section></aside>`;
 return `<aside class="dp-rail"><section class="dp-rail-section dp-selection">${kicker('01',dp.level===5?'SELECTED PHASE':'PROJECT DOSSIER','dossier')}<div style="margin-top:10px">${pill(claim?statusLabel(claim.status):'Not quantified')} ${claim?cite(claim.source_id):''}</div><h2 class="dp-selected-name">${esc(dp.level===5?(claim?.scope||s.name):s.name)}</h2><p>${dp.level===5?esc(s.name):esc(s.location)}</p><div class="dp-spotlight-number">${claim?unit(claim.value,claim.unit):unit(spatialPower(s,'snapshot'))}</div><p class="dp-boundary">${claim?'Disclosed critical IT scope':'Independent snapshot IT estimate'}</p><p class="dp-note">${esc(claim?.qualifier||s.snapshot?.evidence||'No comparable IT-MW quantity is established.')}</p><div class="dp-selection-actions">${link('dossier','Full project dossier ↗','','dp-primary')}${link('add-compare','Compare','','dp-quiet')}</div></section><section class="dp-rail-section">${kicker('02','KEY TAKEAWAYS','evidence')}<h2>Read the boundary<br>before the number.</h2><div class="dp-research-buttons">${link('tab','01 &nbsp; Compare disclosed power scopes','power')}${link('tab','02 &nbsp; Follow the dated development timeline','timeline')}${link('tab','03 &nbsp; Inspect hardware and design evidence','technical')}</div></section><section class="dp-rail-section">${kicker('03','COUNTERPARTIES','counterparties')}<div class="dp-counterparties">${primaryRelationships(s).slice(0,5).map(rel=>{const c=company(rel.company_id);return link('company',`<span>${esc((c?.name||rel.company_id).slice(0,2).toUpperCase())}</span>${esc(c?.name||rel.company_id)}`,rel.company_id);}).join('')}</div><p class="dp-note">Owner, operator and customer roles remain source-specific. ${sources(s).length} primary documents support this project.</p></section></aside>`;}
 function powerPanel(){const s=selected(),rows=itRows(s);const data=rows.length?rows:['snapshot','target'].filter(p=>spatialPower(s,p)!=null).map(p=>({scope:p==='snapshot'?'Dated snapshot':'Projected end-state',value:spatialPower(s,p),unit:'MW',as_of:s[p]?.date,status:'Independent estimate'}));const max=Math.max(1,...data.map(r=>r.value));return `<section class="dp-detail">${kicker('04','POWER BUILDOUT / IT SCOPE')}<h3>${mapped()?'Power not established.':'Each scope keeps its boundary.'}</h3>${mapped()?'<p>Source geometry supplies no IT-capacity value. An independently reviewed disclosure is required.</p>':data.map(r=>`<div class="dp-power-row"><span>${esc(r.scope)}<small>${esc(statusLabel(r.status))}</small></span><span class="dp-power-track"><i style="width:${r.value/max*100}%;background:${['delivered','operating'].includes(r.status)?'#95e7c0':r.status==='under_construction'?'#97b7ed':'#788faf'}"></i></span><b>${unit(r.value,r.unit)}</b></div>`).join('')}<p class="dp-note">${mapped()?'No conversion from floor area or display height to capacity.':'Overlapping scopes and different reporting dates are not additive. Gross facility power remains separate.'}</p></section>`;}
 function attributesPanel(){const s=selected(),r=mappedRecord();const facts=mapped()?[['Feature type','Source-tagged building'],['Operator','Equinix'],['Source geometry','OSM version '+r.source_version],['Measured height','Not tagged'],['Critical IT load','Not established']]:[['Reported location',s.location],['Owner / association',s.owner_label],['Location precision','City / county research anchor'],['Hardware',s.hardware?.map(h=>h.model).join(', ')||'Not disclosed'],['Project sources',String(sources(s).length)+' primary documents']];return `<section class="dp-detail">${kicker('05','FACILITY ATTRIBUTES')}<h3>The physical record.</h3>${facts.map(([l,v])=>`<div class="dp-attribute"><span>${esc(l)}</span><b>${esc(v)}</b></div>`).join('')}<p class="dp-note">${mapped()?'Display height is illustrative. Geometry remains attributed to its own feature.':'Source disclosures appear in the dossier. No building-level footprint is established for this project.'}</p></section>`;}
 function documentsPanel(){const docs=mapped()?[{id:'OSM',title:'Equinix PA9X mapped building',publisher:'OpenStreetMap',published_at:mappedRecord().updated_at.slice(0,10)}]:sources(selected()).slice(0,4);return `<section class="dp-detail">${kicker('06','SOURCES & EVIDENCE','evidence')}<h3>Open the original record.</h3>${docs.map(doc=>`<div class="dp-document"><span class="dp-source-icon">▤</span>${link(doc.id==='OSM'?'geometry-source':'source',`${esc(doc.title)}<small>${esc(doc.publisher||doc.issuer||'Source publisher')} · ${esc(doc.id)}</small>`,doc.id)}<time>${esc(doc.published_at||doc.date||'Undated')}</time></div>`).join('')}${link('evidence','View all sources & revisions ↗','','dp-text')}</section>`;}
 function notesPanel(){return `<section class="dp-detail">${kicker('07','YOUR RESEARCH NOTES')}<h3>Keep the question in view.</h3><textarea class="dp-notes-input" data-dp-note placeholder="What needs verifying? Add a note for this project…">${esc(dp.notes[dp.site]||'')}</textarea><div class="dp-notes-actions"><span>Prototype notes last for this session.</span>${link('export-notes','Export notes ↓','','dp-text')}</div></section>`;}
 function details(){return `<div class="dp-details">${powerPanel()}${attributesPanel()}${documentsPanel()}${notesPanel()}</div>`;}
 function tabPanel(){if(dp.tab==='overview')return '';if(mapped()){const r=mappedRecord();if(dp.tab==='evidence')return '<div class="dp-inline-panel">'+documentsPanel()+'</div>';if(dp.tab==='power')return '<div class="dp-inline-panel">'+powerPanel()+'</div>';if(dp.tab==='timeline')return '<section class="dp-inline-panel"><h3>Source geometry history</h3><div class="dp-timeline"><div class="dp-timeline-item"><time>'+esc(r.updated_at.slice(0,10))+'</time><div>OSM feature version '+r.source_version+'<p>Mapped edit date; no construction milestone is implied.</p></div></div></div></section>';if(dp.tab==='counterparties')return '<section class="dp-inline-panel"><h3>Mapped operator tag</h3><p>'+esc(r.operator)+' · attributed to this community record. Additional project roles are not established.</p></section>';return '<div class="dp-inline-panel">'+attributesPanel()+'</div>';}const s=selected();if(dp.tab==='power')return `<div class="dp-inline-panel"><div class="dp-details">${powerPanel()}${attributesPanel()}</div></div>`;if(dp.tab==='timeline'){const events=[...primaryObservations(s),...primaryFacts(s)].filter(r=>r.as_of).sort((a,b)=>a.as_of.localeCompare(b.as_of)).slice(-7);return `<section class="dp-inline-panel"><h3>Development chronology</h3><p>Reporting dates remain attached to the source statement.</p><div class="dp-timeline">${events.length?events.map(r=>`<div class="dp-timeline-item"><time>${esc(r.as_of)}</time><div><b>${esc(r.scope||r.field||r.metric)}</b><p>${esc(r.qualifier||r.value)}</p>${cite(r.source_id)}</div></div>`).join(''):'<p>No dated project milestones are established in this prototype dataset.</p>'}</div></section>`;}if(dp.tab==='counterparties')return `<section class="dp-inline-panel"><h3>The project’s counterparties</h3>${primaryRelationships(s).map(r=>`<div class="dp-relationship"><span>${esc(r.role)}</span><div>${link('company',esc(company(r.company_id)?.name||r.company_id),r.company_id)} ${cite(r.source_id)}</div></div>`).join('')||'<p>No project-specific counterparty relationship is established.</p>'}</section>`;if(dp.tab==='evidence')return `<div class="dp-inline-panel">${documentsPanel()}</div>`;return `<section class="dp-inline-panel"><h3>Technical design & hardware</h3>${(s.hardware||[]).map(h=>`<div class="dp-attribute"><span>${esc(h.model)}</span><b>${number(h.count)} · ${esc(h.basis||'Basis not disclosed')}</b></div>`).join('')||'<p>Hardware quantities are not established for this project.</p>'}<p class="dp-note">Model assumptions and reported inventories retain distinct labels. Cooling and energy specifications open the cited dossier.</p>${link('dossier','Inspect all technical claims ↗','','dp-text')}</section>`;}
 function recordList(sc,show=false){return `<section class="dp-inline-panel dp-record-list" ${show?'':'hidden'}><div class="dp-list-heading"><h3>Projects in this view</h3>${link('filter','Refine view ≡','','dp-quiet')}</div><table class="dp-table"><thead><tr><th>PROJECT</th><th>COUNTRY</th><th>SNAPSHOT IT</th><th>TARGET IT</th><th>COMPARE</th></tr></thead><tbody>${sc.sites.slice(0,15).map(s=>`<tr><td>${link('select',`${esc(s.name)}<small>${esc(s.location)}</small>`,s.id)}</td><td>${esc(s.country)}</td><td>${unit(spatialPower(s,'snapshot'))}</td><td>${unit(spatialPower(s,'target'))}</td><td>${link('add-compare',dp.compare.includes(s.id)?'✓':'+',s.id)}</td></tr>`).join('')}</tbody></table><p class="dp-note">First ${Math.min(sc.sites.length,15)} of ${sc.sites.length} named research records. A production directory will provide pagination and export.</p></section>`;}
 function landscape(){const sc=scope();return `${intro()}${dp.level>=4?tabs():''}<div class="dp-workspace"><div class="dp-map-column">${mapPanel(sc)}${dp.level<4?kpis(sc):''}<div class="dp-map-attribution"><span>${dp.level<4?'Partial named-project research · approximate anchors':'Source-linked geometry and project evidence retain separate identities'}</span>${link('method','Sources, coverage & methodology ↗')}</div>${dp.level>=4?(dp.tab==='overview'?details():tabPanel()):''}</div>${rail(sc)}</div>${dp.level<4?recordList(sc,dp.page==='directory'||dp.showList):''}`;}
 function auxiliaryPage(){const sc=scope();if(dp.page==='directory')return `${intro()}<div class="dp-project-actions">${link('page','← Return to the landscape','landscape','dp-text')}${link('filter','Refine projects ≡','','dp-quiet')}</div>${recordList(sc,true)}`;if(dp.page==='companies')return `<div class="dp-intro"><div><div class="dp-eyebrow">COMPANY UNIVERSE</div><h1>The companies behind compute.</h1></div><div class="dp-intro-aside"><p>Explore reported finance, named facilities and counterparties, with each measurement boundary intact.</p></div></div><table class="dp-table"><thead><tr><th>COMPANY</th><th>ROLE</th><th>NAMED PROJECTS</th><th>FINANCIAL CONTEXT</th></tr></thead><tbody>${D.companies.map(c=>`<tr><td>${link('company',esc(c.name),c.id)}</td><td>${esc(c.role)}</td><td>${D.sites.filter(s=>s.company_ids.includes(c.id)).length}</td><td>${c.commitment?esc(c.commitment.period):'Not disclosed'}</td></tr>`).join('')}</tbody></table>`;if(dp.page==='investment')return `<div class="dp-intro"><div><div class="dp-eyebrow">INVESTMENT LENS</div><h1>Capital has different boundaries.</h1></div><div class="dp-intro-aside"><p>Period spending, future obligations and backlog remain independent. Historical figures keep their dates.</p></div></div><table class="dp-table"><thead><tr><th>ISSUER / PERIOD</th><th>CAPEX</th><th>OCF</th><th>UNCOMMENCED LEASES</th><th>RPO / BACKLOG</th></tr></thead><tbody>${D.companies.filter(c=>c.commitment).map(c=>`<tr><td>${link('company',`${esc(c.name)}<small>${esc(c.commitment.period)}</small>`,c.id)}</td><td>${money(c.commitment.capex_b)}</td><td>${money(c.commitment.ocf_b)}</td><td>${money(c.commitment.uncommenced_leases_b)}</td><td>${money(c.commitment.rpo_b)}</td></tr>`).join('')}</tbody></table><p class="dp-note">These rows are historical research records. They are not current market data, company fleets or project-level financial allocations.</p>`;if(dp.page==='connections')return `<div class="dp-intro"><div><div class="dp-eyebrow">CONTRACTS & CONNECTIONS</div><h1>Who owns, operates and contracts.</h1></div><div class="dp-intro-aside"><p>Counterparty links retain project, role, source and scope. A customer contract does not become capacity.</p></div></div><table class="dp-table"><thead><tr><th>PROJECT</th><th>ROLE</th><th>COUNTERPARTY</th><th>SOURCE</th></tr></thead><tbody>${effectivePrimary(ATLAS_PRIMARY.relationships).slice(0,30).map(r=>`<tr><td>${link('select',esc(site(r.site_id)?.name||r.site_id),r.site_id)}</td><td>${esc(r.role)}</td><td>${link('company',esc(company(r.company_id)?.name||r.company_id),r.company_id)}</td><td>${cite(r.source_id)}</td></tr>`).join('')}</tbody></table>`;return `<div class="dp-intro"><div><div class="dp-eyebrow">RESEARCH LIBRARY</div><h1>Follow every claim to its source.</h1></div><div class="dp-intro-aside"><p>Research dossiers, original attachments and source revisions share one discovery path.</p></div></div>${recordList(sc,true)}`;}
 function mountMap(){const canvas=document.getElementById('dp-map');if(!canvas)return;if(mapped()){map=new FacilityScene(canvas,mappedRecord(),CATALOG.records);map.setContext(dp.level===4);map.pitch=.85;map.dirty=true;map.canvas.addEventListener('atlas-feature-select',()=>toast('Selected source geometry. Its identity remains independent of research-project phases.'));return;}
 syncResearch();map=new ResearchMap(canvas);map.scope=scope();map.labels=dp.labels;map.level=dp.level;
 if(dp.region!=='all'){const camera=catalogCameras[dp.region];if(camera){map.lat=camera[0];map.lon=camera[1];map.zoom=camera[2];}}
 // Preserve the real map renderer, while prototyping click-to-inspect rather than
 // forcing every marker click through a semantic zoom transition.
 map.pointerUp=function(event){if(!this.drag)return;const moved=this.drag.moved;this.drag=null;if(moved)return;const rect=canvas.getBoundingClientRect();const x=event.clientX-rect.left,y=event.clientY-rect.top;const hit=this.groups.find(g=>Math.hypot(g.x-x,g.y-y)<g.r+8);if(hit){if(dp.level<=1)go({site:hit.sites[0].id,level:Math.min(2,dp.level+1)});else go({site:hit.sites[0].id});}};
 const originalMarkers=map.drawMarkers;
 map.drawMarkers=function(){
  const show=this.labels;this.labels=false;originalMarkers.call(this);this.labels=show;this.markerLabels=[];
  if(!show)return;const c=this.ctx,rect=canvas.getBoundingClientRect();
  const exclusions=[...canvas.parentElement.querySelectorAll('.dp-map-top,.dp-map-scale,.dp-map-legend,.dp-map-bottom,.dp-layer-panel')].map(el=>{const r=el.getBoundingClientRect();return {x:r.left-rect.left,y:r.top-rect.top,w:r.width,h:r.height};});
  const geography=s=>s.country==='United States'?(s.lon< -110?'US West':s.lon< -94&&s.lat<37?'Texas & South':s.lon< -79&&s.lat>37?'US Midwest':'US East'):s.country==='China'?(s.lat>35?'North China':'South China'):s.country;
  for(const g of [...this.groups].sort((a,b)=>Number(b.sites.some(s=>s.id===dp.site))-Number(a.sites.some(s=>s.id===dp.site))||(b.mw||0)-(a.mw||0))){
   const s=g.sites[0],cluster=this.level<=1,regions=new Set(g.sites.map(geography)),countries=new Set(g.sites.map(s=>s.country)),continents=new Set(g.sites.map(spatialContinent));const area=regions.size===1?geography(s):countries.size===1?s.country:continents.size===1?spatialContinent(s):'Mixed-region';const name=cluster?area+(g.sites.length>1?' cluster':''):s.name;
   const text=name.length>26?name.slice(0,24)+'…':name;c.font='11px Arial';const width=Math.max(c.measureText(text).width,120);
   let x=g.x+g.r+9;if(x+width>this.w-15)x=g.x-g.r-width-9;const y=g.y-16;
   if(x<10||y<100||y>this.h-125||exclusions.some(b=>x+width>b.x&&x<b.x+b.w&&y+31>b.y&&y<b.y+b.h)||this.markerLabels.some(b=>x+width>b.x-10&&x<b.x+b.w+10&&Math.abs(y-b.y)<42))continue;
   c.save();c.shadowColor='#04121b';c.shadowBlur=5;c.fillStyle='#e6f6f0';c.fillText(text,x,y+10);c.font='9px monospace';c.fillStyle='#8fbec4';c.fillText(g.mw==null?'Native / unquantified':unit(g.mw)+(cluster?' · '+g.sites.length+(g.sites.length===1?' record':' records'):' · estimate'),x,y+25);c.restore();this.markerLabels.push({x,y,w:width});
   if(this.markerLabels.length>=(this.w<500?3:7))break;
  }
 };
 map.wheel=function(event){if(event.ctrlKey)return;event.preventDefault();const rect=canvas.getBoundingClientRect(),delta=event.deltaY*(event.deltaMode===1?16:1);this.zoomTo(this.zoom*Math.exp(-Math.max(-250,Math.min(250,delta))*.002),{x:event.clientX-rect.left,y:event.clientY-rect.top});};
 // Context can be inspected without treating its points as capacity.
 if(!dp.context){const inherited=map.draw;map.draw=function(){const original=CATALOG;CATALOG={...CATALOG,records:[]};try{return inherited.call(this);}finally{CATALOG=original;}};}
 map.dirty=true;
 }
 function switcher(){return `<div class="dp-review-switcher" aria-label="Prototype layout variation"><small>DESIGN PROTOTYPE</small>${link('variant-prev','←')}<strong>${dp.variant} · ${variants[dp.variant]}</strong>${link('variant-next','→')}</div><div class="dp-review-tools">${link('scenario',dp.scene==='mapped'?'Example: mapped facility':'Example: research project')}${link('state','State { }')}</div>${dp.showState?`<pre class="dp-review-state">${esc(JSON.stringify({variant:dp.variant,scale:levels[dp.level],selection:mapped()?mappedRecord().id:dp.site,phase:dp.phase,claim:dp.claim,tab:dp.tab,filters:{country:dp.country,company:dp.company,evidence:dp.evidence},layers:{context:dp.context,roads:dp.roads,labels:dp.labels},compare:dp.compare,notes:'memory only'},null,2))}</pre>`:''}`;}
 function draw(){if(map){map.destroy();map=null;}if(globe){globe.destroy();globe=null;}document.querySelector('#dp-root')?.remove();document.body.classList.add('dp-design');document.body.classList.remove('variant-a','variant-b','variant-c');document.body.classList.add('variant-'+dp.variant.toLowerCase());const root=document.createElement('div');root.id='dp-root';root.className='dp-level-'+dp.level+(dp.level>=4?' dp-facility':'');root.innerHTML=`<div class="dp-shell">${sidebar()}<main class="dp-main">${topbar()}${dp.page==='landscape'?landscape():auxiliaryPage()}<footer class="dp-foot"><span>Compute Atlas · Source-cited infrastructure & capital.</span>${link('method','Sources, coverage & audit trail ↗')}</footer></main></div>${switcher()}`;document.body.append(root);mountMap();if(dp.expanded)document.body.classList.add('dp-map-expanded');else document.body.classList.remove('dp-map-expanded');renderModal();renderDrawer();document.documentElement.classList.add('design-ready');}
 function searchMatches(query){const q=query.toLowerCase().trim();return D.sites.filter(s=>!q||[s.name,s.country,s.location,s.owner_label].join(' ').toLowerCase().includes(q)).slice(0,8);}
 function renderSearchResults(){const result=document.querySelector('.dp-search-results');if(!result)return;const projects=searchMatches(dp.search);const companies=D.companies.filter(c=>dp.search&&c.name.toLowerCase().includes(dp.search.toLowerCase())).slice(0,3);result.innerHTML=projects.map(s=>link('search-select',`<span class="dp-result-kind">PROJECT</span><span>${esc(s.name)}<small>${esc(s.location)} · ${esc(s.owner_label)}</small></span>`,s.id)).join('')+companies.map(c=>link('search-company',`<span class="dp-result-kind">COMPANY</span><span>${esc(c.name)}<small>${esc(c.role)}</small></span>`,c.id)).join('');if(!projects.length&&!companies.length)result.innerHTML='<p style="padding:25px">No matching project or company. Try a place or operator.</p>';}
 function renderModal(){document.querySelector('.dp-modal-scrim')?.remove();if(!dp.modal)return;const el=document.createElement('div');el.className='dp-modal-scrim';el.innerHTML=dp.modal==='search'?`<section class="dp-modal" role="dialog" aria-modal="true" aria-label="Search atlas"><header class="dp-modal-head"><span>⌕</span><input id="dp-search" type="search" placeholder="Find a facility, company or place…" value="${esc(dp.search)}" aria-label="Search atlas">${link('close-modal','Esc')}</header><div class="dp-search-results"></div><footer class="dp-modal-foot">Project and company search are interactive. Production search adds sources, claims, reports and original files.</footer></section>`:`<section class="dp-modal" role="dialog" aria-modal="true" aria-label="Refine map view"><header class="dp-modal-head"><h3>Refine the landscape.</h3>${link('close-modal','✕')}</header><div class="dp-filter-form"><label>Country<select data-dp-filter="country"><option value="all">All countries</option>${[...new Set(D.sites.map(s=>s.country))].sort().map(c=>`<option ${dp.country===c?'selected':''}>${esc(c)}</option>`).join('')}</select></label><label>Company / operator<select data-dp-filter="company"><option value="all">All counterparties</option>${D.companies.map(c=>`<option value="${c.id}" ${dp.company===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label><label>Evidence basis<select data-dp-filter="evidence">${[['all','All evidence'],['primary','Has primary-source claims'],['reviewed-model','Reviewed independent estimate'],['archive','Imported independent estimate'],['native','Native units / contract only']].map(([v,l])=>`<option value="${v}" ${dp.evidence===v?'selected':''}>${l}</option>`).join('')}</select></label>${link('apply-filters','Apply filters →','','dp-primary')}</div></section>`;document.body.append(el);if(dp.modal==='search'){renderSearchResults();setTimeout(()=>document.getElementById('dp-search')?.focus(),0);}}
 function drawerContent(){const s=selected();if(dp.drawer.kind==='source'){const doc=primarySource(dp.drawer.id)||source(dp.drawer.id);return `<h2>${esc(doc?.title||dp.drawer.id)}</h2><p class="dp-drawer-copy">${esc(doc?.publisher||doc?.issuer||'Source publisher')}</p><dl><dt>Source ID</dt><dd>${esc(doc?.id)}</dd><dt>Publication date</dt><dd>${esc(doc?.published_at||doc?.date||'Not disclosed')}</dd><dt>Retrieved</dt><dd>${esc(doc?.retrieved_at||'Not recorded')}</dd><dt>Review basis</dt><dd>${esc(doc?.review_status||doc?.review||'Not disclosed')}</dd></dl><p class="dp-drawer-copy">Claims retain this document’s locator, scope, native unit and reporting date. A revised source enters review before it replaces accepted evidence.</p>${doc?.url?`<div class="dp-drawer-actions"><a href="${esc(doc.url)}" target="_blank" rel="noopener noreferrer" class="dp-primary">Open original source ↗</a></div>`:''}`;}
 if(dp.drawer.kind==='company'){const c=company(dp.drawer.id);return `<h2>${esc(c?.name||dp.drawer.id)}</h2><p class="dp-drawer-copy">${esc(c?.thesis||'Source-specific company relationships.')}</p><dl><dt>Role</dt><dd>${esc(c?.role)}</dd><dt>Financial period</dt><dd>${esc(c?.commitment?.period||'Not disclosed')}</dd><dt>Period capex</dt><dd>${money(c?.commitment?.capex_b)}</dd><dt>Operating cash flow</dt><dd>${money(c?.commitment?.ocf_b)}</dd><dt>Future leases</dt><dd>${money(c?.commitment?.uncommenced_leases_b)}</dd><dt>RPO / backlog</dt><dd>${money(c?.commitment?.rpo_b)}</dd></dl><p class="dp-drawer-copy">${esc(c?.commitment?.notes||c?.risk||'Unknown financial figures remain undisclosed.')}</p><h3>Named project footprint</h3>${D.sites.filter(x=>x.company_ids.includes(c?.id)).slice(0,8).map(x=>link('search-select',esc(x.name)+' ↗',x.id,'dp-rank')).join('')}`;}
 if(dp.drawer.kind==='compare'){const xs=dp.compare.map(site).filter(Boolean);return `<h2>Compare project evidence.</h2><p class="dp-drawer-copy">Select up to three projects. Different dates and quantity boundaries remain visible.</p>${xs.length?`<table class="dp-table"><thead><tr><th>PROJECT</th><th>SNAPSHOT IT</th><th>TARGET IT</th></tr></thead><tbody>${xs.map(x=>`<tr><td>${esc(x.name)}<small>${esc(x.snapshot?.date||'No dated snapshot')}</small></td><td>${unit(spatialPower(x,'snapshot'))}</td><td>${unit(spatialPower(x,'target'))}</td></tr>`).join('')}</tbody></table>`:'<p class="dp-drawer-copy">Add a project from the selected-project panel or directory.</p>'}<p class="dp-drawer-copy">No combined capacity total is shown: targets can overlap existing phases, and measurements are mixed-vintage estimates.</p>${link('page','Browse projects →','directory','dp-primary')}`;}
 if(dp.drawer.kind==='geometry'){const r=mappedRecord();return `<h2>A spatial view, with a traceable identity.</h2><p class="dp-drawer-copy">The mapped example uses ${esc(r.name)} (${esc(r.id)}). This demonstrates the spatial layout with real source geometry, independently of the Helios and New Carlisle research records.</p><h3>Required before a campus map ships</h3><dl><dt>Identity</dt><dd>Exact operator/project match, address and source IDs.</dd><dt>Coordinates</dt><dd>Reviewed facility location with precision basis.</dd><dt>Geometry</dt><dd>Attributed parcel/building outlines; version and retrieval date.</dd><dt>Imagery</dt><dd>Redistribution rights, attribution, capture date and resolution.</dd><dt>Phase links</dt><dd>Documented building-to-phase correspondence.</dd><dt>Fallback</dt><dd>Source-linked evidence diagram when spatial facts are absent.</dd></dl><p class="dp-drawer-copy">Illustrative heights remain removable. No capacity is inferred from footprint area, building count or proximity to infrastructure.</p><a href="${esc(r.source_url)}" target="_blank" rel="noopener noreferrer" class="dp-primary">Open the geometry source ↗</a>`;}
 if(dp.drawer.kind==='dossier'){return `<h2>${esc(s.name)}</h2><p class="dp-drawer-copy">${esc(s.location)} · ${esc(s.owner_label)}</p><div class="dp-drawer-actions">${link('tab','Power','power','dp-quiet')}${link('tab','Timeline','timeline','dp-quiet')}${link('tab','Sources','evidence','dp-quiet')}</div>${primaryObservations(s).slice(0,8).map(r=>`<div class="dp-detail" style="margin-top:16px"><h3>${esc(r.scope||r.metric)}</h3><p>${esc(r.value)} ${esc(r.unit)} · ${esc(r.boundary)} · ${esc(r.as_of||'Date not disclosed')}</p><p class="dp-drawer-copy">${esc(r.qualifier||'')}</p>${cite(r.source_id)}</div>`).join('')}`;}
 if(dp.drawer.kind==='tour')return `<h2>From the world to one claim.</h2><p class="dp-drawer-copy">Five stops connect geography, project phases, counterparties and investment context.</p>${[['world','Start with the global landscape',0],['continent','See North America and Europe',1],['region','Inspect the East and Midwest',2],['metro','Follow New Carlisle’s local context',3],['campus','Inspect a sourced phase at Helios',4]].map(([,label,level])=>link('tour-stop',`${level+1} &nbsp; ${label} →`,level,'dp-rank')).join('')}`;
 if(dp.drawer.kind==='shelf')return `<h2>Your research shelf.</h2><p class="dp-drawer-copy">The production design unifies saved projects, comparisons, notes and source-review questions. This prototype keeps its state in memory.</p><h3>Session notes</h3>${Object.entries(dp.notes).map(([id,n])=>`<div class="dp-detail"><h3>${esc(site(id)?.name||id)}</h3><p>${esc(n)}</p></div>`).join('')||'<p>No notes yet. Add a note on a campus or facility screen.</p>'}`;
 if(dp.drawer.kind==='monitor')return `<h2>Sources & updates.</h2><p class="dp-drawer-copy">A compact operations surface tracks publication status and pending evidence changes.</p><dl><dt>Publication</dt><dd>Dated accepted research</dd><dt>Source states</dt><dd>Current · changed · unavailable · deferred</dd><dt>Review queue</dt><dd>Candidate claim → compare revision → accept/reject</dd><dt>Quantity changes</dt><dd>Accepted only through explicit source review</dd></dl><p class="dp-drawer-copy">Counts in this design panel are deliberately absent: prototype status is not a running monitor.</p>`;
 return `<h2>Evidence before aggregation.</h2><p class="dp-drawer-copy">This design uses the existing 79-project research graph and independently attributed community locations. A named-site subtotal is partial research coverage.</p><dl><dt>IT / gross</dt><dd>Critical IT load and total facility power remain different quantities.</dd><dt>Snapshot / target</dt><dd>Different dated estimates; targets are not incremental additions.</dd><dt>Geometry</dt><dd>Source outlines do not establish surveyed dimensions or operating capacity.</dd><dt>Roles</dt><dd>Owner, operator, tenant and customer remain source-specific.</dd><dt>Cartography</dt><dd>Natural Earth geography and roads; OpenStreetMap feature context.</dd><dt>Offline mode</dt><dd>Dated publication, no acquisition-running indicator.</dd></dl><p class="dp-drawer-copy">The design calls for sourced imagery and reviewed infrastructure overlays. Missing layers expose a clear reason and a review path.</p>`;
 }
 function renderDrawer(){document.querySelector('.dp-drawer')?.remove();document.querySelector('.dp-drawer-scrim')?.remove();if(!dp.drawer)return;const scrim=document.createElement('div');scrim.className='dp-drawer-scrim';scrim.dataset.dp='close-drawer';const el=document.createElement('aside');el.className='dp-drawer';el.setAttribute('role','dialog');el.setAttribute('aria-modal','true');el.setAttribute('aria-label','Research detail');el.innerHTML=`<header class="dp-drawer-head"><span>RESEARCH & EVIDENCE</span>${link('close-drawer','✕')}</header>${drawerContent()}`;document.body.append(scrim,el);}
 function open(kind,id=null){lastFocus=document.activeElement;dp.drawer={kind,id};renderDrawer();document.querySelector('.dp-drawer [data-dp="close-drawer"]')?.focus();}
 function cycle(delta){const keys=Object.keys(variants);go({variant:keys[(keys.indexOf(dp.variant)+delta+keys.length)%keys.length]},true);}
 function act(action,value){switch(action){case 'home':go({page:'landscape',level:0,region:'all'});break;case 'page':dp.drawer=null;go({page:value});break;case 'level':dp.drawer=null;go({level:Number(value),page:'landscape'});break;case 'select':go({site:value,page:'landscape',scene:'research',level:Math.max(2,dp.level)});break;case 'search-select':dp.modal=null;dp.drawer=null;go({site:value,page:'landscape',scene:'research',level:4});break;case 'search-company':dp.modal=null;renderModal();open('company',value);break;case 'phase':go({phase:value});break;case 'region':go({region:value});break;case 'tab':dp.drawer=null;go({tab:value,level:Math.max(4,dp.level),page:'landscape'});break;case 'claim':go({claim:value,level:5});break;case 'scene':go({scene:value});break;case 'layers':dp.layers=!dp.layers;draw();break;case 'labels':dp.labels=!dp.labels;draw();break;case 'zoom':if(map)map.zoomTo(map.zoom*(value==='in'?1.3:1/1.3));break;case 'reset':if(map){if(map instanceof FacilityScene)map.reset();else{map.zoomTo(1);map.lat=24;map.lon=-18;map.dirty=true;}}break;case 'expand':dp.expanded=!dp.expanded;draw();break;case 'menu':document.querySelector('.dp-side').classList.toggle('open');break;case 'filter':dp.modal='filter';renderModal();break;case 'search':dp.modal='search';renderModal();break;case 'close-modal':dp.modal=null;renderModal();break;case 'apply-filters':dp.modal=null;go({country:document.querySelector('[data-dp-filter="country"]').value,company:document.querySelector('[data-dp-filter="company"]').value,evidence:document.querySelector('[data-dp-filter="evidence"]').value});break;case 'clear-filters':go({country:'all',company:'all',evidence:'all',region:'all'});break;case 'close-drawer':dp.drawer=null;renderDrawer();lastFocus?.focus();break;case 'source':open('source',value);break;case 'company':open('company',value);break;case 'dossier':open('dossier');break;case 'geometry-plan':case 'geometry-source':open('geometry');break;case 'method':open('method');break;case 'monitor':open('monitor');break;case 'shelf':open('shelf');break;case 'tour':open('tour');break;case 'tour-stop':dp.drawer=null;go({level:Number(value),site:Number(value)===4?'coreweave-helios':'amazon-anthropic-new-carlisle',scene:'research',page:'landscape'});break;case 'compare':open('compare');break;case 'add-compare':{const id=value||dp.site;if(dp.compare.includes(id))dp.compare=dp.compare.filter(x=>x!==id);else if(dp.compare.length<3)dp.compare.push(id);else{toast('Compare up to three projects. Remove one to add another.');return;}toast(dp.compare.length+' project'+(dp.compare.length===1?'':'s')+' in comparison');if(dp.page==='directory')draw();break;}case 'investment':go({page:'investment'});break;case 'directory':go({page:'directory'});break;case 'timeline':go({level:4,tab:'timeline',scene:'research'});break;case 'evidence':go({level:4,tab:'evidence'});break;case 'counterparties':go({level:4,tab:'counterparties',scene:'research'});break;case 'list':dp.showList=!dp.showList;draw();document.querySelector('.dp-record-list')?.scrollIntoView({behavior:'smooth'});break;case 'state':dp.showState=!dp.showState;draw();break;case 'variant-next':cycle(1);break;case 'variant-prev':cycle(-1);break;case 'scenario':go({level:Math.max(4,dp.level),scene:dp.scene==='mapped'?'research':'mapped',site:'coreweave-helios',tab:'overview'});break;case 'export-notes':{const blob=new Blob([JSON.stringify(dp.notes,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='compute-atlas-prototype-notes.json';a.click();URL.revokeObjectURL(a.href);break;}}}
 document.addEventListener('click',event=>{const button=event.target.closest('[data-dp]');if(!button)return;event.preventDefault();event.stopImmediatePropagation();act(button.dataset.dp,button.dataset.value);},true);
 document.addEventListener('input',event=>{if(event.target.id==='dp-search'){dp.search=event.target.value;renderSearchResults();}if(event.target.matches('[data-dp-note]'))dp.notes[dp.site]=event.target.value;});
 document.addEventListener('change',event=>{if(event.target.dataset.dpLayer){dp[event.target.dataset.dpLayer]=event.target.checked;draw();}});
 document.addEventListener('keydown',event=>{const editing=event.target.matches('input,textarea,select,[contenteditable=true]');if(event.key==='Escape'){event.preventDefault();event.stopImmediatePropagation();dp.modal=null;dp.drawer=null;dp.expanded=false;dp.layers=false;draw();return;}if(editing)return;if(event.key==='/'||(event.key.toLowerCase()==='k'&&(event.metaKey||event.ctrlKey))){event.preventDefault();event.stopImmediatePropagation();dp.modal='search';renderModal();}else if(['ArrowLeft','ArrowRight'].includes(event.key)&&event.target.tagName!=='CANVAS'){event.preventDefault();event.stopImmediatePropagation();cycle(event.key==='ArrowLeft'?-1:1);}},true);
 window.addEventListener('popstate',()=>{const p=new URLSearchParams(location.search);dp.variant=p.get('variant')||'A';dp.level=Math.max(0,levels.map(x=>x.toLowerCase()).indexOf(p.get('scale')||'world'));dp.site=p.get('site')||'amazon-anthropic-new-carlisle';dp.phase=p.get('phase')||'snapshot';dp.tab=p.get('tab')||'overview';dp.scene=p.get('scene')||'research';dp.claim=p.get('claim')||'helios-phase1-it';dp.country=p.get('country')||'all';draw();});
 // Source module timers may request render after bootstrap. Keep those inside
 // the prototype without carrying their navigation/persistence into this UI.
 render=draw;updateURL(true);draw();
 window.ATLAS_DESIGN={state:dp,render:draw,go,map:()=>map};
})();
